window.docContents[240].resolve({"/Equiv/#Hoare-Logic--Equiv___-Program-Equivalence--Program-Transformation":{"contents":"\n\ndef Aexp.trans_sound (trans : Aexp → Aexp) : Prop :=\n  ∀ (a : Aexp),\n    a.Equiv (trans a)\n\ndef Bexp.trans_sound (trans : Bexp → Bexp) : Prop :=\n  ∀ (b : Bexp),\n    b.Equiv (trans b)\n\ndef Com.trans_sound (trans : Com → Com) : Prop :=\n  ∀ (c : Com),\n    c.Equiv (trans c)\n\n\n\n\n\n\n","context":"Hoare Logic\u0009Equiv: Program Equivalence","header":"4.3. Program Transformation","id":"/Equiv/#Hoare-Logic--Equiv___-Program-Equivalence--Program-Transformation"}});